sys_script_include.script:
var EventRescheduleHelper = Class.create();
EventRescheduleHelper.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	rescheduleEvent: function() {
        var eventId = gs.getParameter('sysparm_event_id');
        var newDate = gs.getParameter('sysparm_new_date');

        if (!eventId || !newDate) {
            return "Invalid parameters.";
        }

        var eventRecord = new GlideRecord('x_1610434_event_0_event_record'); 
        if (eventRecord.get(eventId)) {  
            eventRecord.setValue('event_date', newDate);
            eventRecord.update();
            gs.info("Event successfully rescheduled to: " + newDate);

            return "success";
        } else {
            gs.info("Event record not found for ID: " + eventId);
            return "Event not found.";
        }

    },  

    type: 'EventRescheduleHelper'
});
